function readStoredLanguage() {
  try {
    const direct = localStorage.getItem(I18N_KEY);
    if (direct && T[direct]) return direct;
    const settings = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    if (settings.language && T[settings.language]) return settings.language;
  } catch {}
  try {
    const baseLang = String(navigator?.language || "").toLowerCase().split("-")[0];
    if (T[baseLang]) return baseLang;
  } catch {}
  return "fr";
}

const I18nContext = createContext(null);

export function I18nProvider({ children }) {
  const [language, setLanguageState] = useState(readStoredLanguage);
  useEffect(() => {
    const apply = (lang) => {
      const code = T[lang] ? lang : "fr";
      setLanguageState(code);
      document.documentElement.lang = code;
      document.documentElement.dir = SUPPORTED_LANGUAGES.find(x => x.code === code)?.dir || "ltr";
    };
    apply(language);
    const onSettings = () => apply(readStoredLanguage());
    window.addEventListener("marlin-settings-changed", onSettings);
    window.addEventListener("marlin-language-changed", onSettings);
    return () => {
      window.removeEventListener("marlin-settings-changed", onSettings);
      window.removeEventListener("marlin-language-changed", onSettings);
    };
  }, [language]);

  const value = useMemo(() => ({
    language,
    languages: SUPPORTED_LANGUAGES,
    setLanguage: (code) => {
      if (!T[code]) return;
      setLanguageState(code);
      try { localStorage.setItem(I18N_KEY, code); } catch {}
      const dir = SUPPORTED_LANGUAGES.find(x => x.code === code)?.dir || "ltr";
      document.documentElement.lang = code;
      document.documentElement.dir = dir;
      window.dispatchEvent(new Event("marlin-language-changed"));
    },
    t: (key, fallback = key) => {
      const parts = String(key).split(".");
      let obj = T[language];
      for (const p of parts) obj = obj?.[p];
      if (typeof obj === "string") return obj;
      obj = EXTRA[language];
      for (const p of parts) obj = obj?.[p];
      if (typeof obj === "string") return obj;
      obj = MORE[language];
      for (const p of parts) obj = obj?.[p];
      if (typeof obj === "string") return obj;
      if (parts[0] === "calculator") {
        obj = CALCULATOR_TRANSLATIONS[language];
        for (const p of parts.slice(1)) obj = obj?.[p];
        if (typeof obj === "string") return obj;
      }
      obj = MORE2[language];
      for (const p of parts) obj = obj?.[p];
      if (typeof obj === "string") return obj;
      return fallback;
    },
    categoryMeta: (id, fallback) => {
      const tuple = CATEGORY_TRANSLATIONS[language]?.[id] || CATEGORY_TRANSLATIONS.fr[id];
      if (!tuple) return fallback;
      const [name,purpose,when,hardware,prerequisites,warnings,test] = tuple;
      return { ...fallback, name, purpose, when, hardware, prerequisites, warnings, test };
    }
  }), [language]);

  return React.createElement(I18nContext.Provider, { value }, children);
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error("useI18n must be used within I18nProvider");
  return context;
}
